import { defineStore } from 'pinia';
import { reactive } from 'vue';

export interface HeroState {
  home: {
    heroText: string;
    description: string;
  };
  blog: {
    heroText: string;
    description: string;
  };
  about: {
    heroText: string;
    description: string;
  };
  learn: {
    heroText: string;
    description: string;
  };
  todo: {
    heroText: string;
    description: string;
  };
  parallax: {
    heroText: string;
    description: string;
  };
}

export const useHeroStore = defineStore('heroStore', () => {
  const state = reactive<HeroState>({
    home: {
      heroText: 'Добро пожаловать!',
      description: 'Это главная страница нашего сайта, где вы найдёте всё самое интересное!',
    },
    blog: {
      heroText: 'Блог',
      description: 'Читайте наши последние статьи и новости в блоге.',
    },
    about: {
      heroText: 'О нас',
      description: 'Узнайте больше о нашей команде и миссии.',
    },
    learn: {
      heroText: 'Обучение',
      description: 'Узнайте больше о разработке вместе с нами',
    },
    todo: {
      heroText: 'Задачник',
      description: 'Создавайте задачи и совершенствуйтесь в их выполнении',
    },
    parallax: {
      heroText: 'Параллакс',
      description: 'Создавайте задачи и совершенствуйтесь в их выполнении',
    },
  });

  // Универсальный геттер
  function getContent(routeName: keyof HeroState, key: 'heroText' | 'description', fallback = '') {
    // Проверяем, существует ли маршрут
    if (state[routeName] && state[routeName][key]) {
      return state[routeName][key];
    }

    // Возвращаем значение по умолчанию
    return fallback;
  }

  return {
    getContent,
  };
});
<script setup>
import {useAuth} from '@/utils/common';
import {computed} from "vue";
import { useRoute } from '#imports';
import {useHeroStore} from "@/store/hero";

const heroStore = useHeroStore();
const { isAuthenticated, currentUsername } = useAuth();
const route = useRoute();

function useHeroContent(key, fallback) {
  return computed(() => heroStore.getContent(route.name, key, fallback));
}
const heroText = useHeroContent('heroText', 'Страница');
const description = useHeroContent('description', 'Описание страницы');

//кнопка только для домашней страницы
const isHomePage = computed(() => route.name === 'home');

</script>

<template>
  <section class="hero">
    <div class="container">
      <div class="hero__content">
        <h1 class="hero__headline">{{ heroText || 'Страница' }}</h1>
        <p class="hero__desc">
          {{ description || 'Описание страницы' }}
        </p>
        <div v-if="isAuthenticated" class="name-user name-user--xl text-no-wrap hover--yellow">
          {{ currentUsername }}
        </div>
        <NuxtLink
          v-if="isHomePage"
          to="/about"
          class="btn btn--default"
        >
          <span>Узнать больше о нас</span>
        </NuxtLink>
      </div>
    </div>
  </section>
</template>
